#!/usr/bin/env python3
"""Generate a self-contained, filterable HTML case study from committed JSON."""
import csv,html,json,shutil
from collections import Counter
from pathlib import Path
R=Path(__file__).resolve().parents[1];SITE=R/"site"
apps=json.loads((R/"data/apps.json").read_text(encoding="utf-8"))
review=json.loads((R/"audit/sample_review.json").read_text(encoding="utf-8"))
prior=json.loads((R/"audit/prior_comparison.json").read_text(encoding="utf-8"))
categories=Counter(x["category"] for x in apps);access=Counter(x["credential_access"] for x in apps);mcp=Counter(x["mcp_status"] for x in apps);verdict=Counter(x["buildability"] for x in apps);auth=Counter(a for x in apps for a in x["auth_methods"]);api=Counter(x["api_type"] for x in apps)
urlrefs=sum(len(x.get("evidence_urls",[])) for x in apps);summary=review["summary"]
def e(v):return html.escape(str(v if v is not None else ""))
def links(urls):
 return " ".join('<a target="_blank" rel="noopener noreferrer" href="'+e(u)+'">source '+str(i+1)+'</a>' for i,u in enumerate(urls))
rows=[]
for x in apps:
 rows.append("<tr data-cat='"+e(x["category"])+"' data-access='"+e(x["credential_access"])+"' data-mcp='"+e(x["mcp_status"])+"' data-verdict='"+e(x["buildability"])+"'><td>"+e(x["id"])+"</td><td><b>"+e(x["app"])+"</b><small>"+e(x["description"])+"</small></td><td>"+e(x["category"])+"</td><td>"+e(", ".join(x["auth_methods"]))+"</td><td>"+e(x["credential_access"])+"</td><td>"+e(x["api_type"]+" · "+x["api_breadth"])+"</td><td>"+e(x["mcp_status"])+"</td><td><b>"+e(x["buildability"])+"</b><small>"+e(x["blocker"])+"</small></td><td>"+links(x.get("evidence_urls",[]))+"</td><td>"+e(x.get("confidence"))+"<small>"+e(x.get("provenance",{}).get("claim_status",""))+"</small></td></tr>")
def listcount(c):return "<ul>"+"".join("<li><b>"+e(k)+"</b>: "+str(v)+"</li>" for k,v in c.most_common())+"</ul>"
html_doc='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Composio 100-app research · case study</title><style>
:root{font-family:system-ui,Segoe UI,sans-serif;color:#182635;background:#f4f7fa}*{box-sizing:border-box}body{margin:0;line-height:1.5}header{background:#142c3b;color:#fff;padding:38px max(20px,calc((100vw - 1250px)/2))}header p{max-width:850px;color:#d5e2e9}main{max-width:1250px;margin:auto;padding:22px}.callout,.card{background:#fff;border:1px solid #dce4ea;border-radius:13px;padding:18px;margin:14px 0}.callout{border-left:5px solid #b87822}.kpis,.cols{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.kpi strong{font-size:29px;display:block}.muted,small{font-size:12px;color:#607080;display:block}.filters{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.filters input,.filters select{padding:10px;border:1px solid #b9c7d2;border-radius:8px;background:white}.tablewrap{overflow:auto;background:#fff;border:1px solid #dce4ea;border-radius:12px}table{border-collapse:collapse;min-width:1500px;width:100%;font-size:13px}th{position:sticky;top:0;background:#e8eff4;text-align:left}td,th{padding:10px;border-bottom:1px solid #e2e8ed;vertical-align:top}td small{max-width:300px;margin-top:4px}a{color:#075e9b;margin-right:4px}.pill{display:inline-block;padding:3px 7px;background:#e9f0f5;border-radius:20px;font-size:12px}h2{margin-top:28px}footer{padding:30px;color:#637280} @media(max-width:600px){main{padding:12px}header{padding:26px 18px}}</style></head><body><header><small style="color:#c6d8e2">RESEARCH CASE STUDY · REPRODUCIBLE ARTIFACT</small><h1>100 app integrations: research, evidence, and buildability</h1><p>Composio app toolkit feasibility study. The page is generated from the committed normalized inventory and audit records; use the filters and evidence links to inspect any row.</p></header><main>
<div class="callout"><b>Provenance & limitations.</b> All 100 app records are extracted from the Qwen transcript supplied by the user; this repo does not claim a fresh independent 100-app research pass. Evidence URLs are references, not proof every field is correct. The targeted sample was reviewed by the assistant against source pages, not by an external human. A production credential flow, upstream API call, and Composio SDK execution were not run here. Candidate classifications require continued claim-level validation.</div>
<section class="kpis"><div class="card kpi"><strong>100</strong><span>inventory rows · 10 categories × 10</span></div><div class="card kpi"><strong>''' + str(urlrefs) + '''</strong><span>source URL references, not all audited</span></div><div class="card kpi"><strong>''' + str(summary["reviewed_apps"]) + ''' / ''' + str(summary["field_claims"]) + '''</strong><span>sampled apps / field claims</span></div><div class="card kpi"><strong>''' + str(summary["first_pass_supported"]) + ''' + ''' + str(summary["first_pass_corrected"]) + '''</strong><span>initially supported + corrected in selected sample</span></div><div class="card kpi"><strong>''' + str(summary["not_established_or_unscored"]) + '''</strong><span>sample claims not established / unscored</span></div></section>
<h2>Headline patterns in the transcript-derived inventory</h2><section class="cols"><div class="card"><h3>Credential access</h3>''' + listcount(access) + '''</div><div class="card"><h3>Authentication (overlapping)</h3>''' + listcount(auth) + '''</div><div class="card"><h3>API type</h3>''' + listcount(api) + '''</div><div class="card"><h3>MCP labels</h3>''' + listcount(mcp) + '''</div><div class="card"><h3>Buildability labels</h3>''' + listcount(verdict) + '''</div><div class="card"><h3>Category coverage</h3>''' + listcount(categories) + '''</div></section>
<p class="muted">These counts describe the provided sample, not the full Composio catalog or current verified access rates. OAuth/API key counts overlap. “None” means none recorded in this transcript.</p>
<h2>Verification result: explicit, bounded</h2><section class="card"><p><b>Source-review sample:</b> ''' + str(summary["first_pass_supported"]) + ''' / ''' + str(summary["source_resolvable_claims"]) + ''' claims supported on first pass (''' + f'{summary["first_pass_agreement"]:.1%}' + '''); ''' + str(summary["first_pass_corrected"]) + ''' claims were corrected; ''' + str(summary["not_established_or_unscored"]) + ''' were not established or unscored. After corrections, source alignment is ''' + f'{summary["post_correction_source_alignment"]:.0%}' + ''' among the 64 source-resolvable claims in this selected sample. The reviewer was the assistant—not an independent human—and the sample is not statistically representative. Do not describe this as overall model or dataset accuracy.</p><p><b>Blind-prior concordance:</b> ''' + str(prior["reproduction"]["matching_transcript_labels"]) + ''' / ''' + str(prior["reproduction"]["scored_fields"]) + ''' fields agree with transcript labels; ''' + str(prior["reproduction"]["disagreeing_transcript_labels"]) + ''' disagree. This is label concordance, not factual accuracy. Prior source and hash are included in the audit folder.</p><p><b>Independent spot checks:</b> eight targeted official-source checks, with nuances recorded in <a href="../audit/crosscheck.json">crosscheck.json</a>.</p></section>
<h2>All 100 app findings (transcript-extracted candidate inventory)</h2><p><a href="data/apps.json">JSON dataset</a> · <a href="data/apps.csv">CSV dataset</a> · <a href="audit/sample_review.json">sample review ledger</a> · <a href="audit/verification_summary.json">verification summary</a> · <a href="../README.md">repository methodology</a></p>
<div class="filters"><input id="q" placeholder="Search app, blocker, category…" aria-label="Search"><select id="cat"><option value="">All categories</option>''' + "".join('<option>'+e(k)+'</option>' for k in sorted(categories)) + '''</select><select id="access"><option value="">All access</option>''' + "".join('<option>'+e(k)+'</option>' for k in sorted(access)) + '''</select><select id="mcp"><option value="">All MCP</option>''' + "".join('<option>'+e(k)+'</option>' for k in sorted(mcp)) + '''</select><select id="verdict"><option value="">All verdicts</option>''' + "".join('<option>'+e(k)+'</option>' for k in sorted(verdict)) + '''</select><span id="shown" class="pill">100 rows</span></div>
<div class="tablewrap"><table><thead><tr><th>ID</th><th>App / summary</th><th>Category</th><th>Auth</th><th>Access</th><th>API surface</th><th>MCP</th><th>Buildability / blocker</th><th>Evidence links</th><th>Confidence / provenance</th></tr></thead><tbody id="rows">''' + "".join(rows) + '''</tbody></table></div>
<footer>Generated by src/build_report.py from data/apps.json and audit/*.json. The HTML and JSON are machine-readable enough for review; all operational claims remain bounded by provenance stated above.</footer></main><script>
const q=document.querySelector("#q"),sel=["cat","access","mcp","verdict"].map(x=>document.querySelector("#"+x)),rows=[...document.querySelectorAll("#rows tr")];function filter(){let n=0;rows.forEach(r=>{let ok=(!q.value||r.innerText.toLowerCase().includes(q.value.toLowerCase()))&&sel.every((s,i)=>!s.value||r.dataset[["cat","access","mcp","verdict"][i]]===s.value);r.hidden=!ok;if(ok)n++});document.querySelector("#shown").textContent=n+" / 100 rows"}q.addEventListener("input",filter);sel.forEach(x=>x.addEventListener("change",filter));
</script></body></html>'''
SITE.mkdir(exist_ok=True)
(SITE/"index.html").write_text(html_doc,encoding="utf-8")
for src,dst in [(R/"data/apps.json",SITE/"data/apps.json"),(R/"data/apps.csv",SITE/"data/apps.csv"),(R/"audit/sample_review.json",SITE/"audit/sample_review.json"),(R/"audit/crosscheck.json",SITE/"audit/crosscheck.json"),(R/"audit/prior_comparison.json",SITE/"audit/prior_comparison.json"),(R/"audit/blind_priors.json",SITE/"audit/blind_priors.json")]:
 dst.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(src,dst)
print(f"built {SITE/'index.html'}; rows={len(apps)}; evidence_refs={urlrefs}; reviewed_claims={summary['field_claims']}")
